--- 设置界面信息
---@param skillCatView any
function UIBattlingSkillCatDescGroup:SetPanelInfo(skillCatView)
    -- 猫图
    self.AImg_Cat:LoadSprite(skillCatView.catImgPath)
    -- 星级
    self.StarProgressNode:SetStarNo(Constants.CardMaxStar, 0, skillCatView.star)
    -- -- 技能名
    self.Txt_SkillName.text = skillCatView.skillName
    -- 技能描述
    ---@type CardProgressionSkillUtils
    local CardProgressionSkillUtils = import("Game.CardProgression.CardProgressionSkillUtils")
    self.Txt_SkillDesc.text = CardProgressionSkillUtils.ParseCardTalentDesc(skillCatView.skillDesc, skillCatView.passiveSkillStar, skillCatView.talentVo)
    -- 名字
    self.Txt_CatName.text = skillCatView.catName
    -- 稀有度
    self.SImg_Quality.Status = skillCatView.rare
    -- 属性
    local attrTag = string.format("%d_%d", skillCatView.type, skillCatView.subType)
    local iconPath = Constants.SkillCatTypeIconPath[attrTag]
    self.AImg_Attribute:LoadSprite(iconPath)
end

return UIBattlingSkillCatDescGroup